import { expect, test, uniqueName } from "../../fixtures";

test.describe("vendor name uniqueness", () => {
  test("vendor names are unique within a tenant, ignoring case", { tag: "@VEN-03" }, async ({ apiAs }) => {
    // Arrange: an existing vendor in the member's tenant
    const member = await apiAs("member");
    const existingName = uniqueName("Acme Freight");
    const existing = await member.post("/api/vendors", {
      data: { name: existingName, category: "logistics", contact_email: "ops@acmefreight.example" },
    });
    expect(existing.status(), await existing.text()).toBe(201);

    // Act: same name in a different case
    const duplicate = await member.post("/api/vendors", {
      data: {
        name: existingName.toLowerCase(),
        category: "logistics",
        contact_email: "ops@acmefreight.example",
      },
    });

    // Assert
    const body = await duplicate.text();
    expect(duplicate.status(), body).toBe(409);
    expect(JSON.parse(body).error.code, body).toBe("vendor_name_taken");
  });
});
